// PERSO-4422 Left Authoritarian report, ES + DE (unverified). SP = keys whose EN ends with a space.
const MODE = 'test';
const SP = [];
const T = {"959968989":{"es":"Justicia, responsabilidad colectiva y un Estado fuerte que marque el rumbo","de":"Gerechtigkeit, gemeinsame Verantwortung und ein starker, lenkender Staat"},"959968990":{"es":"Tus resultados te sitúan en el cuadrante de la izquierda autoritaria: crees que una sociedad justa necesita igualdad económica y un Estado fuerte y organizado que la haga posible.","de":"Dein Ergebnis liegt im links-autoritären Quadranten. Menschen in diesem Quadranten sind überzeugt: Eine gerechte Gesellschaft braucht wirtschaftliche Gleichheit und einen starken, gut organisierten Staat, der sie verwirklicht."},"959968991":{"es":"En este contexto, «autoritario» no significa apoyar una dictadura. Describe una preferencia por el orden, la estructura y las normas compartidas por encima de la máxima libertad individual.","de":"„Autoritär“ bedeutet hier nicht, eine Diktatur zu unterstützen. Gemeint ist, dass Ordnung, Struktur und gemeinsame Regeln Vorrang vor größtmöglicher individueller Freiheit haben."},"959968992":{"es":"El mercado, si se deja a su aire, genera demasiada desigualdad","de":"Sich selbst überlassene Märkte erzeugen zu viel Ungleichheit"},"959968993":{"es":"El Estado debe tener un papel protagonista en la economía","de":"Der Staat sollte in der Wirtschaft eine führende Rolle spielen"},"959968994":{"es":"Los objetivos comunes importan más que la ambición individual","de":"Gemeinsame Ziele sind wichtiger als persönlicher Ehrgeiz"},"959968995":{"es":"Tiendes a pensar que:","de":"Du bist eher davon überzeugt, dass:"},"959968996":{"es":"Donde otras personas ven en el Gobierno una amenaza para la libertad, tú ves la herramienta más poderosa para proteger a quienes, de otro modo, se quedarían atrás.","de":"Wo andere im Staat eine Gefahr für die Freiheit sehen, siehst du das wirksamste Mittel, um Menschen zu schützen, die sonst zurückbleiben würden."},"959968997":{"es":"Tu visión se basa en una idea central: la justicia requiere organización.","de":"Deine Haltung beruht auf einem zentralen Gedanken: Gerechtigkeit braucht Organisation."},"959968998":{"es":"Izquierda autoritaria","de":"Links-autoritär"},"959969029":{"es":"Tiendes a pensar que el cambio duradero llega a través de instituciones fuertes y bien organizadas: gobiernos, organismos públicos y grandes organizaciones colectivas capaces de actuar a gran escala. Para ti, las buenas intenciones importan, pero solo las instituciones pueden convertirlas en resultados que lleguen a todo el mundo.","de":"Du bist eher davon überzeugt, dass dauerhafte Veränderungen von starken, gut organisierten Institutionen ausgehen – von Regierungen, öffentlichen Einrichtungen und großen Kollektiven, die im großen Maßstab handeln können. Gute Absichten zählen für dich, aber nur Institutionen können daraus Ergebnisse machen, die alle erreichen."},"959969030":{"es":"A través de las instituciones","de":"Durch Institutionen"},"959969031":{"es":"En lugar de dejar los resultados al azar, prefieres objetivos claros, planes a largo plazo y avances medibles. Es posible que desconfíes de los cambios que dependen solo de la buena voluntad o de que el mercado se corrija solo con el tiempo.","de":"Statt Ergebnisse dem Zufall zu überlassen, setzt du auf klare Ziele, langfristige Pläne und messbare Fortschritte. Veränderungen, die allein auf guten Willen setzen oder darauf, dass sich Märkte mit der Zeit selbst korrigieren, siehst du vielleicht skeptisch."},"959969032":{"es":"A través de la planificación","de":"Durch Planung"},"959969033":{"es":"Crees que el cambio se consolida cuando las personas se comprometen con él de forma conjunta. Valoras la unidad en torno a un objetivo común, y es posible que te impacientes cuando la división o los debates interminables frenan el avance en asuntos que consideras urgentes.","de":"Du glaubst, dass Veränderungen Bestand haben, wenn Menschen sie gemeinsam tragen. Dir ist Einigkeit hinter einem gemeinsamen Ziel wichtig. Wenn Spaltung oder endlose Debatten den Fortschritt bei Themen bremsen, die du für dringend hältst, wirst du vielleicht ungeduldig."},"959969034":{"es":"A través del compromiso compartido","de":"Durch gemeinsames Engagement"},"959969035":{"es":"Confíes en el Estado más de lo que justifica su historial","de":"Dem Staat mehr vertrauen, als seine Bilanz rechtfertigt"},"959969036":{"es":"Pases por alto cómo se puede hacer un mal uso de las instituciones poderosas","de":"Übersehen, wie mächtige Institutionen missbraucht werden können"},"959969037":{"es":"Des por hecho que las buenas intenciones garantizan buenos resultados","de":"Annehmen, dass gute Absichten gute Ergebnisse garantieren"},"959969038":{"es":"Es posible que:"},"959969039":{"es":"Subestimar los riesgos del poder concentrado","de":"Die Risiken konzentrierter Macht unterschätzen"},"959969040":{"es":"Aceptes restricciones que luego son difíciles de revertir","de":"Einschränkungen akzeptieren, die sich später nur schwer rückgängig machen lassen"},"959969041":{"es":"Subestimes el valor de la discrepancia y el debate","de":"Den Wert von Widerspruch und Debatte unterschätzen"},"959969042":{"es":"Te impacientes con quienes se resisten a las normas colectivas","de":"Ungeduldig mit Menschen werden, die sich gemeinsamen Regeln widersetzen"},"959969043":{"es":"Es posible que:"},"959969044":{"es":"Renunciar a la libertad con demasiada facilidad","de":"Freiheit zu leichtfertig aufgeben"},"959969045":{"es":"Pases por alto el papel de la competencia en la innovación","de":"Die Rolle des Wettbewerbs für Innovation übersehen"},"959969046":{"es":"Subestimes lo ineficiente que puede llegar a ser la planificación centralizada","de":"Unterschätzen, wie ineffizient zentrale Planung werden kann"},"959969047":{"es":"Veas cualquier beneficio económico como algo sospechoso","de":"Jeden Gewinn für verdächtig halten"},"959969048":{"es":"Es posible que:"},"959969049":{"es":"Escepticismo hacia el mercado","de":"Skepsis gegenüber Märkten"},"959969050":{"es":"Veas la oposición como un obstáculo y no como un contrapeso sano","de":"Opposition als Hindernis statt als gesunde Kontrolle sehen"},"959969051":{"es":"Prefieras la unidad al debate abierto","de":"Einigkeit einer offenen Debatte vorziehen"},"959969052":{"es":"Te cueste aceptar las opiniones que anteponen la elección individual","de":"Sich schwertun mit Sichtweisen, bei denen die individuelle Entscheidung an erster Stelle steht"},"959969053":{"es":"Es posible que:"},"959969054":{"es":"Impaciencia ante el desacuerdo","de":"Ungeduld bei Meinungsverschiedenheiten"},"959969055":{"es":"Compartís el compromiso con la justicia económica, unos servicios públicos sólidos y límites al poder de las grandes empresas. En lo que diferís es en cuánta autoridad debe tener el Estado sobre la vida de las personas.","de":"Ihr teilt das Engagement für wirtschaftliche Gerechtigkeit, starke öffentliche Leistungen und Grenzen für die Macht großer Konzerne. Unterschiedlicher Meinung seid ihr darüber, wie viel Macht der Staat über das Leben der Menschen haben sollte."},"959969056":{"es":"Con la izquierda libertaria","de":"Mit Links-Libertären"},"959969057":{"es":"Compartís el respeto por el orden, el deber y la cohesión nacional, y la convicción de que los derechos conllevan responsabilidades. En lo que diferís es en el mercado, los impuestos y el papel de la riqueza privada.","de":"Ihr teilt den Respekt vor Ordnung, Pflicht und nationalem Zusammenhalt sowie die Überzeugung, dass Rechte mit Pflichten einhergehen. Unterschiedlicher Meinung seid ihr bei Märkten, Steuern und der Rolle privaten Vermögens."},"959969058":{"es":"Con la derecha autoritaria","de":"Mit Rechts-Autoritären"},"959969059":{"es":"Es el cuadrante más alejado del tuyo, pero aun así podéis coincidir en oponeros a los privilegios para las grandes empresas y en querer una sociedad que recompense el esfuerzo de forma justa. En lo que diferís es en casi todo lo relativo al papel del Estado.","de":"Dieser Quadrant ist am weitesten von deinem entfernt. Trotzdem seid ihr euch vielleicht einig, dass große Unternehmen keine Sonderbehandlung bekommen sollten und dass Leistung fair belohnt werden sollte. Bei der Rolle des Staates seid ihr dagegen fast überall unterschiedlicher Meinung."},"959969060":{"es":"Con la derecha libertaria","de":"Mit Rechts-Libertären"},"959969061":{"es":"Aunque no estés de acuerdo con las personas de otros cuadrantes, es posible que compartáis más de lo que crees.","de":"Auch wenn du anderer Meinung bist als Menschen aus anderen Quadranten, habt ihr vielleicht mehr gemeinsam, als du denkst."},"959969062":{"es":"Reconocer lo que tenéis en común no significa renunciar a tus ideas: facilita las conversaciones productivas y te ayuda a conseguir apoyo para lo que te importa.","de":"Gemeinsamkeiten zu erkennen, heißt nicht, die eigenen Ansichten aufzugeben. Es erleichtert konstruktive Gespräche und hilft dir, Unterstützung für die Dinge zu gewinnen, die dir wichtig sind."},"959969063":{"es":"En absoluto. Muchas personas de este cuadrante defienden firmemente la democracia. Tu resultado refleja la confianza en unas instituciones públicas fuertes y en normas colectivas, no una oposición a las elecciones ni al debate libre.","de":"Ganz und gar nicht. Viele Menschen in diesem Quadranten stehen fest hinter der Demokratie. Dein Ergebnis spiegelt das Vertrauen in starke öffentliche Institutionen und gemeinsame Regeln wider – keine Ablehnung von Wahlen oder freier Debatte."},"959969064":{"es":"«Izquierda autoritaria significa antidemocrática»","de":"„Links-autoritär heißt antidemokratisch.“"},"959969065":{"es":"No necesariamente. Puede que simplemente creas que los servicios esenciales y los sectores clave deben estar bajo control público, sin dejar de aceptar la iniciativa privada en otros ámbitos.","de":"Nicht unbedingt. Vielleicht bist du einfach überzeugt, dass grundlegende Dienstleistungen und Schlüsselbranchen öffentlich kontrolliert werden sollten, während du private Unternehmen in anderen Bereichen akzeptierst."},"959969066":{"es":"«Seguro que estás en contra de toda empresa privada»","de":"„Dann bist du bestimmt gegen jedes Privatunternehmen.“"},"959969067":{"es":"Sí que te importan: simplemente crees que algunos derechos, como la sanidad, la vivienda o un salario justo, necesitan la protección activa del Estado, y que una libertad ilimitada puede dejar desprotegidas a las personas más vulnerables.","de":"Ganz im Gegenteil. Du bist nur überzeugt, dass manche Rechte – etwa Gesundheitsversorgung, Wohnen und faire Löhne – aktiv vom Staat geschützt werden müssen und dass grenzenlose Freiheit die Schwächsten schutzlos lassen kann."},"959969068":{"es":"«No te importan los derechos individuales»","de":"„Individuelle Rechte sind dir egal.“"},"959969069":{"es":"Crees que una buena sociedad es una sociedad justa, y que la justicia no surge por casualidad.","de":"Für dich ist eine gute Gesellschaft eine gerechte Gesellschaft – und Gerechtigkeit entsteht nicht zufällig."},"959969070":{"es":"Donde otras personas confían en que el mercado o la elección individual lo resuelvan todo, tú recurres al esfuerzo colectivo, la responsabilidad compartida y un Estado lo bastante fuerte como para proteger a quien lo necesita.","de":"Wo andere darauf vertrauen, dass Märkte oder individuelle Entscheidungen alles regeln, setzt du auf gemeinsame Anstrengung, geteilte Verantwortung und einen Staat, der stark genug ist, um die zu schützen, die Schutz brauchen."},"959969071":{"es":"Tu fortaleza es tu compromiso con el bien común.","de":"Deine Stärke ist dein Einsatz für das Gemeinwohl."},"959969072":{"es":"Pero un Estado fuerte solo es tan bueno como los límites que se le imponen.","de":"Doch ein starker Staat ist nur so gut wie die Grenzen, die ihm gesetzt werden."},"959969073":{"es":"Si combinas tu afán de justicia con el respeto a la libertad individual, el debate abierto y unas instituciones que rindan cuentas, podrás convertir tus convicciones en un cambio positivo y duradero.","de":"Wenn du deinen Gerechtigkeitssinn mit Respekt vor individueller Freiheit, offener Debatte und kontrollierbaren Institutionen verbindest, kannst du aus deinen Überzeugungen dauerhafte, positive Veränderungen machen."},"959969074":{"es":"No solo te preguntas qué es justo. Te preguntas cómo construirlo.","de":"Du fragst nicht nur, was gerecht ist. Du fragst, wie man es aufbaut."},"959969075":{"es":"Conclusión"},"959969076":{"es":"Preocuparte de verdad por la brecha entre ricos y pobres","de":"Die Kluft zwischen Arm und Reich sehr ernst zu nehmen"},"959969077":{"es":"Ver la riqueza extrema como un problema para la sociedad, no solo como un logro personal","de":"Extremen Reichtum als Problem für die Gesellschaft zu sehen, nicht nur als persönliche Leistung"},"959969078":{"es":"Apoyar políticas que redistribuyan los recursos","de":"Maßnahmen zu unterstützen, die Ressourcen umverteilen"},"959969079":{"es":"Tiendes a:"},"959969080":{"es":"Los argumentos del «efecto derrame»","de":"„Trickle-down“-Argumente"},"959969081":{"es":"El mercado como principal respuesta a los problemas sociales","de":"Märkte als wichtigste Antwort auf soziale Probleme"},"959969082":{"es":"La riqueza como prueba de mérito","de":"Reichtum als Beweis für Leistung"},"959969083":{"es":"Te convencen menos:","de":"Weniger überzeugen dich:"},"959969084":{"es":"Compromiso con la igualdad económica","de":"Einsatz für wirtschaftliche Gleichheit"},"959969085":{"es":"Los grandes problemas necesitan soluciones grandes y coordinadas","de":"Große Probleme brauchen große, abgestimmte Lösungen"},"959969086":{"es":"Nadie puede acabar por su cuenta con una injusticia estructural","de":"Einzelne allein können strukturelle Ungerechtigkeit nicht beseitigen"},"959969087":{"es":"La sociedad es más fuerte cuando las personas trabajan por objetivos comunes","de":"Eine Gesellschaft ist stärker, wenn Menschen auf gemeinsame Ziele hinarbeiten"},"959969088":{"es":"Crees que:","de":"Du bist überzeugt, dass:"},"959969089":{"es":"Piensas de forma natural en «nosotros» más que en «yo».","de":"Du denkst ganz selbstverständlich in „Wir“ statt in „Ich“."},"959969090":{"es":"Confianza en la acción colectiva","de":"Vertrauen in gemeinsames Handeln"},"959969091":{"es":"Normas claras que se apliquen a todo el mundo","de":"Klare Regeln, die für alle gelten"},"959969092":{"es":"Mano firme con quienes se aprovechan de los demás","de":"Konsequentes Vorgehen gegen alle, die andere ausnutzen"},"959969093":{"es":"La estabilidad por encima del cambio constante","de":"Stabilität statt ständiger Veränderung"},"959969094":{"es":"Es probable que valores:","de":"Wahrscheinlich ist dir wichtig:"},"959969095":{"es":"Para ti, la estructura no es lo contrario de la justicia: es lo que la hace posible.","de":"Für dich ist Struktur nicht das Gegenteil von Gerechtigkeit – sie macht Gerechtigkeit erst möglich."},"959969096":{"es":"Preferencia por el orden y la estructura","de":"Sinn für Ordnung und Struktur"},"959969097":{"es":"Quien pueda contribuir, debe hacerlo","de":"Wer etwas beitragen kann, sollte es auch tun"},"959969098":{"es":"Los derechos conllevan responsabilidades","de":"Rechte gehen mit Pflichten einher"},"959969099":{"es":"Las decisiones personales afectan al conjunto de la comunidad","de":"Persönliche Entscheidungen wirken sich auf die ganze Gemeinschaft aus"},"959969100":{"es":"Tiendes a pensar que:","de":"Du bist eher davon überzeugt, dass:"},"959969101":{"es":"Esperas que la sociedad cuide de las personas y que las personas aporten algo a cambio.","de":"Du erwartest, dass die Gesellschaft sich um die Menschen kümmert – und dass die Menschen etwas zurückgeben."},"959969102":{"es":"Deber y contribución","de":"Pflicht und Beitrag"},"959969103":{"es":"Es probable que lleves las conversaciones hacia la justicia y la visión de conjunto. Cuando otras personas se centran en las decisiones individuales, tú sueles señalar los sistemas que hay detrás. Puede que te frustres cuando alguien desestima la desigualdad como algo natural o inevitable.","de":"Wahrscheinlich lenkst du Gespräche immer wieder auf Gerechtigkeit und das große Ganze. Wenn andere sich auf individuelle Entscheidungen konzentrieren, verweist du eher auf die Systeme dahinter. Es frustriert dich vielleicht, wenn Ungleichheit als natürlich oder unvermeidlich abgetan wird."},"959969104":{"es":"En las conversaciones","de":"In Gesprächen"},"959969105":{"es":"Probablemente valoras la lealtad, la fiabilidad y la responsabilidad compartida. Esperas que las personas de tu entorno cercano arrimen el hombro y se cuiden entre sí, y no tardas en echar una mano cuando alguien de tu círculo lo está pasando mal.","de":"Dir sind Loyalität, Verlässlichkeit und geteilte Verantwortung wahrscheinlich wichtig. Du erwartest, dass die Menschen in deinem Umfeld ihren Teil beitragen und aufeinander achten, und du springst schnell ein, wenn jemand aus deinem Kreis es schwer hat."},"959969106":{"es":"En las relaciones","de":"In Beziehungen"},"959969107":{"es":"Sueles apreciar las estructuras claras y las normas justas. Puede que seas quien alza la voz cuando el reparto del trabajo es injusto, quien apoya los convenios colectivos o quien prefiere organizaciones con un propósito que vaya más allá del beneficio económico.","de":"Du schätzt eher klare Strukturen und faire Regeln. Vielleicht bist du diejenige Person, die sich zu Wort meldet, wenn die Arbeit ungerecht verteilt ist, die Tarifverträge unterstützt oder Organisationen bevorzugt, deren Zweck über den Gewinn hinausgeht."},"959969108":{"es":"En el trabajo","de":"Bei der Arbeit"},"959969109":{"es":"Los valores políticos no solo se reflejan en las urnas. También influyen en cómo hablas, trabajas y te relacionas con las personas que te rodean.","de":"Politische Werte zeigen sich nicht nur an der Wahlurne – sie prägen auch, wie du sprichst, arbeitest und mit den Menschen um dich herum umgehst."},"959969110":{"es":"No. Significa que te inclinas por el orden, la estructura y un Estado fuerte en lugar de por la máxima libertad individual.","de":"Nein. Es bedeutet, dass du eher zu Ordnung, Struktur und einem starken Staat neigst als zu größtmöglicher individueller Freiheit."},"959969111":{"es":"P1: ¿«Autoritario» significa que apoyo la dictadura?","de":"F1: Heißt „autoritär“, dass ich eine Diktatur unterstütze?"},"959969112":{"es":"No. Los partidos combinan posiciones de distintos cuadrantes. Tu resultado describe tus valores, no una opción de voto.","de":"Nein. Parteien verbinden Positionen aus verschiedenen Quadranten. Dein Ergebnis beschreibt deine Werte, keine Wahlentscheidung."},"959969113":{"es":"P2: ¿Este resultado me dice a qué partido votar?","de":"F2: Sagt mir dieses Ergebnis, welche Partei ich wählen soll?"},"959969114":{"es":"No necesariamente. Tu resultado muestra tu tendencia más marcada, y la mayoría de las personas tienen opiniones de más de un cuadrante.","de":"Nicht unbedingt. Dein Ergebnis zeigt deine stärkste Tendenz, und die meisten Menschen haben Ansichten aus mehr als einem Quadranten."},"959969115":{"es":"P3: No estoy de acuerdo con todo lo que pone aquí. ¿Mi resultado es incorrecto?","de":"F3: Ich stimme nicht mit allem hier überein. Ist mein Ergebnis falsch?"},"959969116":{"es":"Sí. Las experiencias vitales, la información nueva y los cambios de circunstancias suelen hacer que las opiniones de las personas evolucionen con el tiempo.","de":"Ja. Lebenserfahrung, neue Informationen und veränderte Umstände lassen Ansichten mit der Zeit oft anders werden."},"959969117":{"es":"P4: ¿Pueden cambiar mis opiniones políticas?","de":"F4: Können sich meine politischen Ansichten ändern?"},"959969118":{"es":"En encontrar el equilibrio entre los objetivos colectivos, la libertad individual y unos buenos contrapesos al poder.","de":"Darauf, gemeinsame Ziele mit individueller Freiheit und wirksamen Kontrollen der Macht in Einklang zu bringen."},"959969119":{"es":"P5: ¿En qué debería centrarme?","de":"F5: Worauf sollte ich mich konzentrieren?"},"959969120":{"es":"No. Muchas personas combinan el deseo de justicia económica con la preferencia por el orden y unas instituciones fuertes.","de":"Nein. Viele Menschen verbinden den Wunsch nach wirtschaftlicher Gerechtigkeit mit einer Vorliebe für Ordnung und starke Institutionen."},"959969121":{"es":"P6: ¿Es raro obtener este resultado?","de":"F6: Ist dieses Ergebnis ungewöhnlich?"},"959969122":{"es":"Valorar la libertad no excluye este resultado. Tus respuestas muestran que, en conjunto, antepones ligeramente los objetivos colectivos y la justicia a la elección individual.","de":"Dass dir Freiheit wichtig ist, schließt dieses Ergebnis nicht aus. Deine Angaben zeigen, dass du gemeinsame Ziele und Gerechtigkeit insgesamt etwas höher gewichtest als die individuelle Entscheidung."},"959969123":{"es":"P7: ¿Por qué he obtenido este resultado si valoro mi libertad?","de":"F7: Warum habe ich dieses Ergebnis, obwohl mir meine Freiheit wichtig ist?"},"959969124":{"es":"Úsalo como punto de partida para reflexionar: para entender tus prioridades, explicar tus ideas a los demás y explorar perspectivas distintas de la tuya.","de":"Nutze es als Ausgangspunkt zum Nachdenken: um deine Prioritäten zu verstehen, anderen deine Ansichten zu erklären und Sichtweisen kennenzulernen, die sich von deiner unterscheiden."},"959969125":{"es":"P8: ¿Cómo puedo usar este resultado?","de":"F8: Wie kann ich dieses Ergebnis nutzen?"},"959969126":{"es":"No. Cada cuadrante refleja un conjunto distinto de valores y prioridades, y cada uno tiene sus propias fortalezas y puntos ciegos. Las sociedades sanas suelen beneficiarse de las perspectivas de los cuatro.","de":"Nein. Jeder Quadrant steht für andere Werte und Prioritäten, und jeder hat seine eigenen Stärken und blinden Flecken. Gesunde Gesellschaften profitieren meist von den Sichtweisen aller vier."},"959969127":{"es":"P9: ¿Hay un cuadrante mejor que los demás?","de":"F9: Ist ein Quadrant besser als die anderen?"},"959969128":{"es":"Preguntas y respuestas"},"959969129":{"es":"Preguntarte cómo podría usar mal una política un futuro Gobierno","de":"Dich fragen, wie eine künftige Regierung eine Maßnahme missbrauchen könnte"},"959969130":{"es":"Apoyar tribunales, medios de comunicación y organismos de control independientes","de":"Unabhängige Gerichte, Medien und Aufsichtsbehörden unterstützen"},"959969131":{"es":"Valorar la transparencia tanto como la eficacia","de":"Transparenz genauso wichtig nehmen wie Wirksamkeit"},"959969132":{"es":"Puedes reforzar tu visión si te acostumbras a:","de":"So kannst du deine Haltung stärken:"},"959969133":{"es":"Incorporar controles y contrapesos","de":"Kontrollen und Gegengewichte einbauen"},"959969134":{"es":"Distinguir lo que debe ser colectivo de lo que puede seguir siendo personal","de":"Unterscheiden, was gemeinsam geregelt werden muss und was persönlich bleiben kann"},"959969135":{"es":"Respetar decisiones que tú no tomarías","de":"Entscheidungen respektieren, die du selbst nicht treffen würdest"},"959969136":{"es":"Reconocer que la libertad también protege a las personas vulnerables","de":"Anerkennen, dass Freiheit auch die Schwachen schützt"},"959969137":{"es":"Podrías beneficiarte de:"},"959969138":{"es":"Dejar espacio a la elección individual","de":"Raum für individuelle Entscheidungen lassen"},"959969139":{"es":"Explorar en qué casos la competencia mejora los servicios","de":"Herausfinden, wo Wettbewerb Leistungen verbessert"},"959969140":{"es":"Analizar modelos mixtos que combinen objetivos públicos con la eficiencia privada","de":"Gemischte Modelle prüfen, die öffentliche Ziele mit privatwirtschaftlicher Effizienz verbinden"},"959969141":{"es":"Juzgar las herramientas económicas por sus resultados, no por sus etiquetas","de":"Wirtschaftliche Instrumente nach ihren Ergebnissen beurteilen, nicht nach ihren Etiketten"},"959969142":{"es":"Puedes:"},"959969143":{"es":"Abrirte a las ideas de mercado","de":"Offen für marktwirtschaftliche Ideen sein"},"959969144":{"es":"Tr